package main

import (
	"fmt"
	"strings"
)

// GeneratedFile 是一个待写入 Models/Generated 的文件。
type GeneratedFile struct {
	Name    string
	Content []byte
}

const generatedHeader = `// <auto-generated>
// 本文件由 tools/alyprotocol 从 spec/aly-protocol.schema.json 生成，请勿手工编辑。
// 重新生成：cd tools/alyprotocol && go run . -write
// </auto-generated>
`

// Render 按 schema 定义顺序渲染 C# 模型；只生成 cfg.Types 中列出的类型。
func Render(s *Schema, cfg *Config) ([]GeneratedFile, error) {
	if err := cfg.normalizeAndValidate(); err != nil {
		return nil, err
	}
	if err := validateRenderConfig(s, cfg); err != nil {
		return nil, err
	}
	var files []GeneratedFile
	for _, def := range s.Defs {
		tc, ok := cfg.Types[def.Name]
		if !ok {
			continue
		}
		content, err := renderObject(s, cfg, def, tc)
		if err != nil {
			return nil, err
		}
		files = append(files, GeneratedFile{
			Name:    tc.Name + ".g.cs",
			Content: []byte(content),
		})
	}
	return files, nil
}

func validateRenderConfig(s *Schema, cfg *Config) error {
	for defName := range cfg.Types {
		if s.Def(defName) == nil {
			return fmt.Errorf("配置引用了 schema 中不存在的定义 %q", defName)
		}
	}
	for key := range cfg.Properties {
		defName, propName, ok := strings.Cut(key, ".")
		if !ok {
			return fmt.Errorf("属性覆盖 %q 必须是 <Def>.<property> 形式", key)
		}
		obj := s.Def(defName)
		if obj == nil {
			return fmt.Errorf("属性覆盖 %q 指向不存在的定义 %q", key, defName)
		}
		if obj.Property(propName) == nil {
			return fmt.Errorf("属性覆盖 %q 指向不存在的属性", key)
		}
		if _, ok := cfg.Types[defName]; !ok {
			return fmt.Errorf("属性覆盖 %q 指向未生成的 C# 类型", key)
		}
	}
	return nil
}

func renderObject(s *Schema, cfg *Config, def *Object, tc TypeConfig) (string, error) {
	var b strings.Builder
	b.WriteString(generatedHeader)
	b.WriteString("\nusing Newtonsoft.Json;\n\n")
	b.WriteString("namespace ")
	b.WriteString(tc.Namespace)
	b.WriteString("\n{\n")
	writeXmlDoc(&b, "    ", def.Description)

	b.WriteString("    ")
	b.WriteString(tc.Visibility)
	b.WriteString(" ")
	if tc.Partial {
		b.WriteString("partial ")
	}
	b.WriteString("class ")
	b.WriteString(tc.Name)
	b.WriteString("\n    {\n")

	first := true
	for _, p := range def.Properties {
		// 无 type 的属性（仅 Output.data）由手写的泛型 AlyResponse<T>.Data 承担。
		if p.Type == "" && p.Ref == "" {
			continue
		}
		typ, err := csharpType(s, cfg, def.Name, p)
		if err != nil {
			return "", fmt.Errorf("%s.%s: %v", def.Name, p.Name, err)
		}
		if !first {
			b.WriteString("\n")
		}
		first = false
		writeXmlDoc(&b, "        ", p.Description)
		b.WriteString("        [JsonProperty(\"")
		b.WriteString(p.Name)
		b.WriteString("\")]\n")
		b.WriteString("        public ")
		b.WriteString(typ)
		b.WriteString(" ")
		b.WriteString(pascalCase(p.Name))
		b.WriteString(" { get; set; }\n")
	}

	b.WriteString("    }\n}\n")
	return b.String(), nil
}

func csharpType(s *Schema, cfg *Config, defName string, p *Property) (string, error) {
	if ov, ok := cfg.Properties[defName+"."+p.Name]; ok {
		return ov.Type, nil
	}
	switch p.Type {
	case "string":
		return "string", nil
	case "boolean":
		return "bool", nil
	case "integer":
		return "long", nil
	case "number":
		return "double", nil
	case "object":
		return refTypeName(s, cfg, p.Ref)
	case "array":
		if p.ItemsRef != "" {
			name, err := refTypeName(s, cfg, p.ItemsRef)
			if err != nil {
				return "", err
			}
			return name + "[]", nil
		}
		switch p.ItemsType {
		case "string":
			return "string[]", nil
		case "boolean":
			return "bool[]", nil
		case "integer":
			return "long[]", nil
		case "number":
			return "double[]", nil
		}
	}
	return "", fmt.Errorf("无法映射到 C# 类型: type=%q items=%q ref=%q", p.Type, p.ItemsType, p.Ref)
}

func refTypeName(s *Schema, cfg *Config, ref string) (string, error) {
	name := strings.TrimPrefix(ref, "#/$defs/")
	if s.Def(name) == nil {
		return "", fmt.Errorf("$ref 指向不存在的定义 %q", name)
	}
	tc, ok := cfg.Types[name]
	if !ok {
		return "", fmt.Errorf("引用了未生成 C# 类型的定义 %q", name)
	}
	return tc.Name, nil
}

func writeXmlDoc(b *strings.Builder, indent, desc string) {
	if strings.TrimSpace(desc) == "" {
		return
	}
	b.WriteString(indent)
	b.WriteString("/// <summary>\n")
	for _, line := range strings.Split(desc, "\n") {
		b.WriteString(indent)
		b.WriteString("/// ")
		b.WriteString(xmlEscape(strings.TrimSpace(line)))
		b.WriteString("\n")
	}
	b.WriteString(indent)
	b.WriteString("/// </summary>\n")
}

var xmlEscaper = strings.NewReplacer("&", "&amp;", "<", "&lt;", ">", "&gt;")

func xmlEscape(s string) string {
	return xmlEscaper.Replace(s)
}

// pascalCase 把 snake_case（或 camelCase）属性名转成 C# 属性名。
func pascalCase(name string) string {
	parts := strings.Split(name, "_")
	for i, p := range parts {
		if p == "" {
			continue
		}
		parts[i] = strings.ToUpper(p[:1]) + p[1:]
	}
	return strings.Join(parts, "")
}